/* Vue SFC grammar, adapted from highlightjs-vue by Sara Lissette Luis Ibáñez.
 * BSD-3-Clause; see ../LICENSE.vue. Supports Vue 3 setup and attribute order. */
(() => {
  hljs.registerLanguage('vue', h => {
    const block = (tag, language, condition = '') => ({
      begin: new RegExp('<' + tag + '\\b' + condition + '[^>]*>'),
      end: new RegExp('</' + tag + '\\s*>'),
      subLanguage: language, excludeBegin: true, excludeEnd: true,
    });
    return {name: 'Vue', subLanguage: 'xml', contains: [
      h.COMMENT('<!--', '-->'),
      block('script', 'typescript', '(?=[^>]*\\blang\\s*=\\s*["\\\'](?:ts|tsx)["\\\'])'),
      block('script', 'javascript'),
      block('style', 'scss', '(?=[^>]*\\blang\\s*=\\s*["\\\']s[ca]ss["\\\'])'),
      block('style', 'stylus', '(?=[^>]*\\blang\\s*=\\s*["\\\']stylus["\\\'])'),
      block('style', 'css'),
      {begin: /\{\{/, end: /\}\}/, subLanguage: 'javascript'},
    ]};
  });
})();
